const runExerciseFallback = (code: string, exerciseIndex: number): string => {
  if (/print\(\s*["']([^"']+)["']\s*\)/.test(code) && exerciseIndex === 0) { const match = code.match(/print\(\s*["']([^"']+)["']\s*\)/); if (!match) throw new Error("Use print(\"your text\")"); return match[1]; }
  if (exerciseIndex === 1) { const width = code.match(/width\s*=\s*([\d.]+)/)?.[1]; const height = code.match(/height\s*=\s*([\d.]+)/)?.[1]; if (!width || !height) throw new Error("Define width and height first"); return String(Number(width) * Number(height)); }
  if (exerciseIndex === 2) { const match = code.match(/print\(\s*add\(\s*([\d.]+)\s*,\s*([\d.]+)\s*\)\s*\)/); if (!match || !/return\s+a\s*\+\s*b/.test(code)) throw new Error("Define add(a, b) and return a + b"); return String(Number(match[1]) + Number(match[2])); }
  if (exerciseIndex === 3) { const match = code.match(/\[\s*([\d.,\s]+)\s*\]/); if (!match || !/sum\s*\(/.test(code)) throw new Error("Create the list and use sum(numbers)"); return String(match[1].split(",").reduce((sum, value) => sum + Number(value), 0)); }
  const match = code.match(/(?:features|values|data)\s*=\s*\[\s*([\d.,\s]+)\s*\]/); if (!match || !/sum\s*\(/.test(code) || !/len\s*\(/.test(code)) throw new Error("Create features, then use total = sum(features) and average = total / len(features)"); return String(match[1].split(",").reduce((sum, value) => sum + Number(value), 0) / match[1].split(",").length);
};

const getExerciseGuide = (exercise: { title: string; titleAr: string; starter: string; prompt: string; promptAr: string }) => {
  const lower = exercise.title.toLowerCase();
  if (lower.includes("variable") || lower.includes("numbers") || lower.includes("division") || lower.includes("remainder")) return { idea: "Store values in meaningful variables, then apply the required arithmetic operation.", ideaAr: "خزّن القيم داخل متغيرات واضحة، ثم نفّذ العملية الحسابية المطلوبة.", steps: ["Create a variable with =.", "Use the variable in an expression.", "Print the final result."], stepsAr: ["أنشئ متغيرًا باستخدام =.", "استخدم المتغير في تعبير حسابي.", "اطبع النتيجة النهائية."] };
  if (lower.includes("if") || lower.includes("classifier") || lower.includes("boolean")) return { idea: "A condition evaluates to True or False and selects which block should run.", ideaAr: "الشرط ينتج True أو False ويحدد أي جزء من الكود سيتم تشغيله.", steps: ["Choose the value to test.", "Write the condition with a colon.", "Indent the code inside the block."], stepsAr: ["حدد القيمة التي تريد فحصها.", "اكتب الشرط وضع : في نهايته.", "استخدم مسافة بادئة داخل كتلة الشرط."] };
  if (lower.includes("loop") || lower.includes("filter") || lower.includes("comprehension")) return { idea: "Repeat an operation for each item, and keep the code inside the loop indented.", ideaAr: "كرّر العملية لكل عنصر، وحافظ على المسافات البادئة داخل الحلقة.", steps: ["Prepare a list or range.", "Choose for, while, or a comprehension.", "Print or collect the result."], stepsAr: ["جهّز قائمة أو range.", "اختر for أو while أو اختصار القائمة.", "اطبع النتيجة أو اجمعها في قائمة."] };
  if (lower.includes("list") || lower.includes("tuple") || lower.includes("set") || lower.includes("dictionary")) return { idea: "A collection stores multiple values so you can access, update, or process them together.", ideaAr: "هيكل البيانات يخزن عدة قيم لتتمكن من الوصول إليها أو تعديلها أو معالجتها معًا.", steps: ["Create the collection.", "Use an index or key when needed.", "Apply a built-in function such as len, sum, or max."], stepsAr: ["أنشئ هيكل البيانات.", "استخدم index أو key عند الحاجة.", "طبّق دالة جاهزة مثل len أو sum أو max."] };
  if (lower.includes("function") || lower.includes("method")) return { idea: "A function groups reusable instructions and returns a useful result.", ideaAr: "الدالة تجمع تعليمات قابلة لإعادة الاستخدام ويمكنها إرجاع نتيجة مفيدة.", steps: ["Write def with a name and parameters.", "Indent the function body.", "Return the result and call the function."], stepsAr: ["اكتب def مع اسم الدالة والمعاملات.", "استخدم مسافة بادئة داخل الدالة.", "أرجع النتيجة ثم استدعِ الدالة."] };
  if (lower.includes("class") || lower.includes("robot")) return { idea: "A class is a blueprint for objects; __init__ stores the object's data.", ideaAr: "الصنف هو مخطط للكائنات، و __init__ يخزن بيانات الكائن.", steps: ["Create a class with class.", "Define __init__ and self.", "Create an object and access its data or method."], stepsAr: ["أنشئ صنفًا باستخدام class.", "عرّف __init__ واستخدم self.", "أنشئ كائنًا ثم استخدم بياناته أو دالته."] };
  if (lower.includes("import") || lower.includes("random")) return { idea: "Import a library when you need a function that Python does not provide directly.", ideaAr: "استورد مكتبة عندما تحتاج إلى وظيفة غير موجودة مباشرة في بايثون.", steps: ["Import the module.", "Call its function with dot notation.", "Print or use the returned value."], stepsAr: ["استورد الوحدة.", "استدعِ دالتها باستخدام النقطة.", "اطبع القيمة الناتجة أو استخدمها."] };
  if (lower.includes("error") || lower.includes("safe")) return { idea: "Handle expected failures with try and except so the program can respond safely.", ideaAr: "عالج الأخطاء المتوقعة باستخدام try و except حتى يستجيب البرنامج بأمان.", steps: ["Put risky code inside try.", "Catch the specific exception.", "Print a helpful fallback message."], stepsAr: ["ضع الكود المحتمل أن يفشل داخل try.", "التقط نوع الخطأ المحدد.", "اطبع رسالة بديلة مفيدة."] };
  return { idea: "Start with the smallest valid Python statement, then print and verify the result.", ideaAr: "ابدأ بأبسط تعليمة Python صحيحة، ثم اطبع النتيجة وتحقق منها.", steps: ["Read the requirement carefully.", "Use the starter code as a template.", "Run the code and compare the output."], stepsAr: ["اقرأ المطلوب بعناية.", "استخدم الكود الابتدائي كقالب.", "شغّل الكود وقارن الناتج بالمطلوب."] };
};

const getExerciseBenefit = (title: string) => {
  const lower = title.toLowerCase();
  if (lower.includes("variable") || lower.includes("numbers") || lower.includes("division") || lower.includes("remainder")) return { en: "This is the foundation for storing measurements, model parameters, scores, and engineering calculations.", ar: "هذا الأساس لخزن القياسات ومعاملات النماذج والدرجات والحسابات الهندسية." };
  if (lower.includes("if") || lower.includes("classifier") || lower.includes("boolean")) return { en: "Conditions are used by AI systems to make decisions, classify inputs, and trigger actions.", ar: "تستخدم الشروط في أنظمة الذكاء الاصطناعي لاتخاذ القرارات وتصنيف المدخلات وتشغيل الأفعال." };
  if (lower.includes("loop") || lower.includes("filter") || lower.includes("comprehension")) return { en: "Iteration lets you process thousands of records, images, features, or sensor readings without repeating code manually.", ar: "الحلقات تمكنك من معالجة آلاف السجلات أو الصور أو السمات أو قراءات الحساسات دون تكرار الكود يدويًا." };
  if (lower.includes("list") || lower.includes("tuple") || lower.includes("set") || lower.includes("dictionary")) return { en: "Collections are essential for organizing datasets, labels, features, and results in AI projects.", ar: "هياكل البيانات أساسية لتنظيم مجموعات البيانات والتسميات والسمات والنتائج في مشاريع الذكاء الاصطناعي." };
  if (lower.includes("function") || lower.includes("method")) return { en: "Reusable functions make large AI programs easier to test, maintain, and share with a team.", ar: "الدوال القابلة لإعادة الاستخدام تجعل برامج الذكاء الاصطناعي الكبيرة أسهل للاختبار والصيانة والعمل الجماعي." };
  if (lower.includes("class") || lower.includes("robot")) return { en: "Classes model real systems such as robots, sensors, datasets, and AI services with their data and behavior.", ar: "تمثل الأصناف أنظمة حقيقية مثل الروبوتات والحساسات ومجموعات البيانات وخدمات الذكاء الاصطناعي مع بياناتها وسلوكها." };
  if (lower.includes("import") || lower.includes("random")) return { en: "Libraries give you reliable tools for mathematics, data processing, simulation, and machine learning.", ar: "المكتبات توفر أدوات موثوقة للرياضيات ومعالجة البيانات والمحاكاة وتعلم الآلة." };
  if (lower.includes("error") || lower.includes("safe")) return { en: "Safe error handling prevents an AI application from crashing when data or external services behave unexpectedly.", ar: "معالجة الأخطاء تمنع تطبيق الذكاء الاصطناعي من التوقف عندما تكون البيانات أو الخدمات الخارجية غير متوقعة." };
  return { en: "This exercise builds the habit of translating a requirement into code, testing the output, and improving the solution.", ar: "يبني هذا التمرين عادة تحويل المتطلبات إلى كود ثم اختبار الناتج وتحسين الحل." };
};

function CourseCard({ course, progress, onOpen }: { course: Course; progress?: Progress; onOpen: () => void }) {
  const value = progress?.progress ?? 0;
  const english = courseEnglish[course.slug];
  const project = courseProjects[course.slug];
  const source = officialSources[course.slug];
  return (
    <button className={`course-card course-card--${course.color}`} onClick={onOpen}>
      <div className="course-card-art">
        <span className="course-art-glyph">{course.color === "cyan" ? "↗" : course.color === "violet" ? "⌘" : course.color === "lime" ? "▦" : "◈"}</span>
        <span className="course-level">{course.level} · {englishLevel[course.level] ?? course.level}</span>
      </div>
      <div className="course-card-copy">
        <h3>{course.title}<small className="course-title-en">{english?.title ?? course.title}</small></h3>
        <p>{course.description}<small className="course-description-en">{english?.description ?? course.description}</small></p>
        <span>{course.lessons.length} دروس · {course.lessons.length} lessons · {course.lessons.reduce((sum, lesson) => sum + Number.parseInt(lesson.duration), 0)} دقيقة / min</span>
        {project && <div className="course-project-brief"><b>مشروع تطبيقي · Practical project</b><strong>{project.title}<small>{project.en}</small></strong><p>{project.brief}</p><span>{project.tools}</span></div>}
        {source && <div className="official-source"><b>Official source · المصدر الرسمي</b><span>{source.label}</span><small>{source.url}</small></div>}
        <div className="progress-track"><i style={{ width: `${value}%` }} /></div>
        <div className="progress-caption"><span>التقدم</span><b>{value}%</b></div>
      </div>
    </button>
  );
}
function PythonPage({ user, progress, onNavigate, onLogout }: { user: User | null; progress: Progress[]; onNavigate: (path: string) => void; onLogout: () => void }) {
  const course = courses.find((item) => item.slug === "python-from-zero")!;
  const saved = progress.find((item) => item.courseSlug === course.slug);
  return <main className="portal-shell python-page"><Topbar user={user} active="python" onNavigate={onNavigate} onLogout={onLogout} /><section className="learning-panel" style={{ width: "100%", margin: "38px auto", direction: "rtl" }}><div className="python-lab-hero"><div><span className="eyebrow">Python Learning Studio · مختبر بايثون</span><h1>اكتب، شغّل، وتعلّم Python</h1><p>تعلّم البرمجة بالتطبيق. اختر تمرينًا، اكتب الكود، شغّله داخل المتصفح، ثم افحص الحل.</p></div><button className="primary-button" onClick={() => onNavigate("/python-lab")}>افتح محرر الكود · Open Code Lab ↗</button></div><div className="course-grid">{course.lessons.map((lesson, index) => <button className="course-card" key={lesson.title} onClick={() => onNavigate(`/courses/${course.slug}/lessons/${index + 1}`)}><div className="course-card-art"><span className="course-art-glyph">Py</span><span className="course-level">الدرس {index + 1}</span></div><div className="course-card-copy"><h3>{lesson.title}</h3><p>{lesson.summary}</p><span>{lesson.quiz.length} أسئلة · {lesson.duration}</span></div></button>)}</div><p className="panel-note">{saved ? `تقدمك الحالي في بايثون: ${saved.progress}%` : "سجّل الدخول لحفظ تقدمك في بايثون"}</p></section></main>;
}

function PythonLabPage({ user, onNavigate, onLogout }: { user: User | null; onNavigate: (path: string) => void; onLogout: () => void }) {
  const [exerciseIndex, setExerciseIndex] = useState(0);
  const [code, setCode] = useState(pythonExercises[0].starter);
  const [output, setOutput] = useState("");
  const [status, setStatus] = useState("");
  const [runtime, setRuntime] = useState<any>(null);
  const [runtimeStatus, setRuntimeStatus] = useState("Loading Python runtime... · جارٍ تجهيز بايثون");
  const exercise = pythonExercises[exerciseIndex];
  const guide = getExerciseGuide(exercise);
  const benefit = getExerciseBenefit(exercise.title);
  useEffect(() => { let cancelled = false; const script = document.createElement("script"); script.src = "https://cdn.jsdelivr.net/pyodide/v0.26.2/full/pyodide.js"; script.async = true; script.onload = async () => { try { const loaded = await (window as any).loadPyodide({ indexURL: "https://cdn.jsdelivr.net/pyodide/v0.26.2/full/" }); if (!cancelled) { setRuntime(loaded); setRuntimeStatus("Ready · جاهز للتشغيل"); } } catch (error) { if (!cancelled) setRuntimeStatus(`Runtime error: ${String(error)} · تعذر تجهيز بايثون`); } }; script.onerror = () => { if (!cancelled) setRuntimeStatus("Could not load Pyodide. Check your internet connection. · تعذر تحميل بايثون"); }; document.head.appendChild(script); return () => { cancelled = true; script.remove(); }; }, []);
  useEffect(() => { setCode(exercise.starter); setOutput(""); setStatus(""); }, [exerciseIndex, exercise.starter]);
  const runCode = async (check = false) => { setStatus("Running... · جارٍ التشغيل"); let cleanOutput = ""; try { if (runtime) { let captured = ""; runtime.setStdout({ batched: (text: string) => { captured += text; } }); runtime.setStderr({ batched: (text: string) => { captured += text; } }); await runtime.runPythonAsync(code); cleanOutput = captured.trim(); } else { cleanOutput = runExerciseFallback(code, exerciseIndex); } setOutput(cleanOutput); if (check) setStatus(cleanOutput === exercise.expected ? "Correct! · إجابة صحيحة" : "Not quite yet. · حاول مرة أخرى"); else setStatus(runtime ? "Finished · اكتمل التشغيل" : "Finished with exercise fallback · اكتمل التشغيل الاحتياطي"); } catch (error) { setOutput(String(error)); setStatus("Python error · خطأ في الكود"); } };
  return <main className="portal-shell python-lab-page"><Topbar user={user} active="python" onNavigate={onNavigate} onLogout={onLogout} /><section className="python-lab-shell"><div className="python-lab-heading"><div><span className="eyebrow">Interactive Python Code Lab · مختبر كود تفاعلي</span><h1>تعلّم Python بالممارسة</h1><p>Write code in English, run it safely in your browser, and translate the exercise instructions when needed.</p></div><button className="secondary-button" onClick={() => onNavigate("/python")}>← العودة لمسار Python</button></div><div className="python-lab-grid"><aside className="python-exercise-list"><span className="eyebrow">Exercises · التمارين</span>{pythonExercises.map((item, index) => <button className={index === exerciseIndex ? "active" : ""} key={item.title} onClick={() => setExerciseIndex(index)}><strong>{String(index + 1).padStart(2, "0")} · {item.title}</strong><small>{item.titleAr}</small></button>)}</aside><section className="python-editor-panel"><div className="exercise-prompt"><span className="course-chip cyan">Task · تمرين {exerciseIndex + 1}</span><span className="runtime-status">{runtimeStatus} · Built-in exercise mode available · وضع التمارين متاح</span><h2>{exercise.title}</h2><p>{exercise.prompt}</p><p className="prompt-ar">{exercise.promptAr}</p></div><div className="python-guide"><div className="python-guide-heading"><strong>Python basics · أساسيات Python</strong><span>Reference · مرجع سريع</span></div><div className="python-guide-grid"><article><b>01 · Print</b><code>print("Hello")</code><p>اطبع نصًا أو نتيجة على الشاشة.</p></article><article><b>02 · Variables</b><code>name = "AI"</code><p>خزّن قيمة داخل متغير واستخدمها لاحقًا.</p></article><article><b>03 · Conditions</b><code>if score &gt;= 70:</code><p>استخدم المسافة البادئة بعد النقطتين.</p></article><article><b>04 · Functions</b><code>def add(a, b):</code><p>قسّم الحل إلى دوال صغيرة قابلة لإعادة الاستخدام.</p></article></div></div><div className="exercise-guide-card"><div className="exercise-guide-title"><strong>Full lesson · شرح التمرين من الصفر إلى النهاية</strong><span>{exercise.titleAr} · شرح خاص بالتمرين</span></div><p><b>Idea · الفكرة:</b> {guide.idea}</p><p className="prompt-ar"><b>الفكرة:</b> {guide.ideaAr}</p><div className="exercise-steps"><div><b>Build it step by step · طريقة الكتابة خطوة بخطوة</b>{guide.steps.map((step, index) => <p key={step}>{index + 1}. {step}</p>)}</div><div><b>الطريقة بالعربي من البداية للنهاية</b>{guide.stepsAr.map((step, index) => <p key={step}>{index + 1}. {step}</p>)}</div></div><div className="exercise-benefit"><b>Why is this useful? · شنو الفائدة؟</b><p>{benefit.en}</p><p className="prompt-ar">{benefit.ar}</p></div><div className="exercise-finish"><b>Finish · النهاية:</b> Run the code, read the output, compare it with the expected result, then change one value and run it again. · شغّل الكود، اقرأ الناتج، قارنه بالمطلوب، ثم غيّر قيمة واحدة وشغّله مرة أخرى.</div><pre className="exercise-starter"><code>{exercise.starter}</code></pre></div><textarea className="python-editor" value={code} onChange={(event) => setCode(event.target.value)} spellCheck={false} aria-label="Python code editor" /><div className="python-actions"><button className="primary-button" onClick={() => void runCode()}>▶ Run code · تشغيل الكود</button><button className="secondary-button" onClick={() => void runCode(true)}>✓ Check exercise · فحص التمرين</button><button className="text-button" onClick={() => setCode(exercise.starter)}>Reset · إعادة</button></div><div className="python-output"><div><span>Output · الناتج</span><span className={status.startsWith("Correct") ? "output-success" : ""}>{status}</span></div><pre>{output || "# Your output will appear here\n# سيظهر الناتج هنا"}</pre></div></section></div></section></main>;
}
