function ExamsPage({ user, onNavigate, onLogout }: { user: User | null; onNavigate: (path: string) => void; onLogout: () => void }) {
  const [level, setLevel] = useState<keyof typeof examQuestions>("beginner"); const [answers, setAnswers] = useState<number[]>([]); const [submitted, setSubmitted] = useState(false); const questions = examQuestions[level]; const score = answers.reduce((sum, answer, i) => sum + (answer === questions[i]?.answer ? 1 : 0), 0);
  const chooseLevel = (next: keyof typeof examQuestions) => { setLevel(next); setAnswers([]); setSubmitted(false); };
  return <main className="portal-shell"><Topbar user={user} active="exams" onNavigate={onNavigate} onLogout={onLogout} /><section className="workspace-shell"><div className="workspace-heading"><div><span className="eyebrow">Assessment Center · مركز الامتحانات</span><h1>اختبر نفسك بثلاثة مستويات</h1><p>اختر المستوى، أجب، ثم اقرأ سبب صحة الإجابة بعد التسليم.</p></div></div><div className="level-tabs">{(["beginner", "intermediate", "advanced"] as const).map((item) => <button className={level === item ? "active" : ""} onClick={() => chooseLevel(item)} key={item}>{item === "beginner" ? "مبتدئ · Beginner" : item === "intermediate" ? "متوسط · Intermediate" : "متقدم · Advanced"}</button>)}</div><section className="exam-list">{questions.map((item, index) => <article className="workspace-card exam-card" key={item.q}><h2>{index + 1}. {item.q}</h2><div className="exam-options">{item.options.map((option, optionIndex) => <label key={option}><input type="radio" name={`q-${index}`} checked={answers[index] === optionIndex} onChange={() => setAnswers((prev) => { const next = [...prev]; next[index] = optionIndex; return next; })} />{option}</label>)}</div>{submitted && <p className={answers[index] === item.answer ? "exam-correct" : "exam-wrong"}>{answers[index] === item.answer ? "Correct · إجابة صحيحة" : `Review · راجع: ${item.why}`}</p>}</article>)}</section><button className="primary-button" onClick={() => setSubmitted(true)}>Submit exam · تسليم الامتحان</button>{submitted && <div className="exam-result">Score: {score}/{questions.length} · نتيجتك {score} من {questions.length}</div>}</section></main>;
}

function ReviewPage({ user, progress, results, onNavigate, onLogout }: { user: User | null; progress: Progress[]; results: QuizResult[]; onNavigate: (path: string) => void; onLogout: () => void }) {
  const weak = results.filter((result) => result.quizScore < result.quizTotal * 0.7).map((result) => ({ result, course: courses.find((item) => item.slug === result.courseSlug) })).filter((item) => item.course);
  const incomplete = progress.filter((item) => item.progress < 100).map((item) => courses.find((course) => course.slug === item.courseSlug)).filter(Boolean);
  return <main className="portal-shell"><Topbar user={user} active="review" onNavigate={onNavigate} onLogout={onLogout} /><section className="workspace-shell"><div className="workspace-heading"><div><span className="eyebrow">Smart Review · المراجعة الذكية</span><h1>راجع ما يحتاج إلى تقوية</h1><p>نقترح عليك الدروس التي لم تتجاوز اختبارها أو المسارات التي لم تكتمل.</p></div></div><div className="review-grid"><section className="workspace-card"><h2>اختبارات تحتاج مراجعة</h2>{weak.length ? weak.map(({ result, course }) => <article className="review-item" key={`${result.courseSlug}-${result.lessonIndex}`}><b>{course?.title}</b><span>Lesson {result.lessonIndex + 1} · Score {result.quizScore}/{result.quizTotal}</span><button className="secondary-button" onClick={() => onNavigate(`/courses/${result.courseSlug}/lessons/${result.lessonIndex + 1}`)}>راجع الدرس</button></article>) : <div className="empty-state">لا توجد اختبارات ضعيفة حاليًا. أحسنت!</div>}</section><section className="workspace-card"><h2>مسارات غير مكتملة</h2>{incomplete.length ? incomplete.map((course) => course && <article className="review-item" key={course.slug}><b>{course.title}</b><span>Progress · {progress.find((item) => item.courseSlug === course.slug)?.progress ?? 0}%</span><button className="secondary-button" onClick={() => onNavigate(`/courses/${course.slug}/lessons/1`)}>واصل التعلم</button></article>) : <div className="empty-state">أكملت كل المسارات المحفوظة.</div>}</section></div></section></main>;
}

