function Login({ onBack }: { onBack: () => void }) {
  const [register, setRegister] = useState(false);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const submit = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError("");
    try {
      const response = await fetch(register ? "/api/auth/register" : "/api/auth/login", { method: "POST", credentials: "include", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name, email, password }) });
      const data = await response.json() as { error?: string };
      if (!response.ok) throw new Error(data.error || "تعذر تسجيل الدخول");
      window.location.assign("/profile");
    } catch (caught) { setError(caught instanceof Error ? caught.message : "تعذر تنفيذ الطلب"); } finally { setBusy(false); }
  };
  return (
    <main className="auth-shell">
      <button className="brand auth-brand" onClick={onBack}>
        <span className="brand-mark">M</span>
        <strong>EngiMind — إنجي مايند</strong>
      </button>
      <section className="auth-card">
        <span className="hero-kicker">✦ ابدأ رحلتك الهندسية</span>
        <h1>{register ? "أنشئ حسابك" : "مرحبًا بك من جديد"}</h1>
        <p>{register ? "أدخل معلوماتك للانضمام إلى EngiMind — منصة الذكاء والهندسة." : "سجّل دخولك لمتابعة تقدمك ومساراتك التعليمية."}</p>
        <form onSubmit={submit} style={{ display: "grid", gap: 12, marginTop: 20 }}>
          {register && <input value={name} onChange={(event) => setName(event.target.value)} placeholder="الاسم الكامل" required minLength={2} />}
          <input value={email} onChange={(event) => setEmail(event.target.value)} type="email" placeholder="البريد الإلكتروني" required />
          <input value={password} onChange={(event) => setPassword(event.target.value)} type="password" placeholder="كلمة المرور (8 أحرف على الأقل)" required minLength={8} />
          {error && <p role="alert" style={{ color: "#ff9a9a" }}>{error}</p>}
          <button className="primary-button" type="submit" disabled={busy}>{busy ? "جارٍ التنفيذ..." : register ? "إنشاء الحساب" : "تسجيل الدخول"}</button>
        </form>
        <button className="text-button" onClick={() => { setRegister(!register); setError(""); }}>{register ? "لديك حساب؟ تسجيل الدخول" : "ليس لديك حساب؟ إنشاء حساب جديد"}</button>{!register && <button className="text-button" onClick={() => { window.location.assign("/forgot-password"); }}>نسيت كلمة المرور؟</button>}
        <div className="auth-divider"><span>دخول آمن ومشفر</span></div>
        <button className="text-button" onClick={onBack}>العودة إلى الصفحة الرئيسية ←</button>
      </section>
    </main>
  );
}

function ForgotPassword({ onBack }: { onBack: () => void }) {
  const [email, setEmail] = useState(""); const [message, setMessage] = useState(""); const [busy, setBusy] = useState(false);
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setMessage(""); try { const response = await fetch("/api/auth/request-reset", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ email }) }); const data = await response.json() as { message?: string }; setMessage(data.message || "تحقق من بريدك الإلكتروني."); } catch { setMessage("تعذر إرسال الطلب حالياً."); } finally { setBusy(false); } };
  return <main className="auth-shell"><button className="brand auth-brand" onClick={onBack}><span className="brand-mark">M</span><strong>EngiMind — إنجي مايند</strong></button><section className="auth-card"><span className="hero-kicker">أمان الحساب</span><h1>نسيت كلمة المرور؟</h1><p>أدخل بريدك، وسنرسل رابطاً صالحاً لمدة 30 دقيقة إذا كان الحساب موجوداً.</p><form onSubmit={submit} style={{ display: "grid", gap: 12, marginTop: 20 }}><input value={email} onChange={(event) => setEmail(event.target.value)} type="email" placeholder="البريد الإلكتروني" required /><button className="primary-button" disabled={busy}>{busy ? "جارٍ الإرسال..." : "إرسال رابط الاستعادة"}</button></form>{message && <p role="status" className="password-message">{message}</p>}<button className="text-button" onClick={onBack}>العودة لتسجيل الدخول ←</button></section></main>;
}
function ResetPassword({ onBack, token }: { onBack: () => void; token: string }) {
  const [password, setPassword] = useState(""); const [message, setMessage] = useState(""); const [done, setDone] = useState(false); const [busy, setBusy] = useState(false);
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setMessage(""); try { const response = await fetch("/api/auth/reset-password", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ token, newPassword: password }) }); const data = await response.json() as { error?: string }; if (!response.ok) throw new Error(data.error || "تعذر تغيير كلمة المرور"); setDone(true); setMessage("تم تغيير كلمة المرور. يمكنك تسجيل الدخول الآن."); } catch (error) { setMessage(error instanceof Error ? error.message : "تعذر تغيير كلمة المرور"); } finally { setBusy(false); } };
  return <main className="auth-shell"><button className="brand auth-brand" onClick={onBack}><span className="brand-mark">M</span><strong>EngiMind — إنجي مايند</strong></button><section className="auth-card"><span className="hero-kicker">تحديث كلمة المرور</span><h1>عيّن كلمة مرور جديدة</h1>{done ? <><p role="status" className="password-message">{message}</p><button className="primary-button" onClick={onBack}>تسجيل الدخول</button></> : <><p>استخدم كلمة مرور جديدة لا تقل عن 8 أحرف.</p><form onSubmit={submit} style={{ display: "grid", gap: 12, marginTop: 20 }}><input value={password} onChange={(event) => setPassword(event.target.value)} type="password" minLength={8} placeholder="كلمة المرور الجديدة" required /><button className="primary-button" disabled={busy}>{busy ? "جارٍ الحفظ..." : "حفظ كلمة المرور"}</button></form>{message && <p role="alert" className="password-message">{message}</p>}</>}<button className="text-button" onClick={onBack}>العودة لتسجيل الدخول ←</button></section></main>;
}

function Profile({ user, progress, results, onNavigate, onLogout }: { user: User; progress: Progress[]; results: QuizResult[]; onNavigate: (path: string) => void; onLogout: () => void }) {
  const average = results.length ? Math.round(results.reduce((sum, result) => sum + Math.round((result.quizScore / result.quizTotal) * 100), 0) / results.length) : 0;
  const done = progress.reduce((sum, item) => sum + item.completedLessons, 0);
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [passwordMessage, setPasswordMessage] = useState("");
  const [passwordBusy, setPasswordBusy] = useState(false);
  const updatePassword = async (event: FormEvent) => { event.preventDefault(); setPasswordBusy(true); setPasswordMessage(""); try { await api("/api/auth/change-password", { method: "POST", body: JSON.stringify({ currentPassword, newPassword }) }); setPasswordMessage("تم تغيير كلمة المرور بنجاح"); setCurrentPassword(""); setNewPassword(""); } catch (error) { setPasswordMessage(error instanceof Error ? error.message : "تعذر تغيير كلمة المرور"); } finally { setPasswordBusy(false); } };

  return (
    <main className="profile-shell">
      <Topbar user={user} active="" onNavigate={onNavigate} onLogout={onLogout} />
      <section className="profile-header">
        <div className="avatar">{user.name.slice(0, 1)}</div>
        <div>
          <span className="eyebrow">ملفي الشخصي</span>
          <h1>{user.name}</h1>
          <p>{user.email}</p>
        </div>
        {user.email.trim().toLowerCase() === "altiahussoni@gmail.com" && <button className="secondary-button" onClick={() => onNavigate("/admin")}>إدارة الأعضاء</button>}
        <button className="secondary-button" onClick={onLogout}>تسجيل الخروج ↪</button>
      </section>
      <section className="profile-metrics">
        <div><span>متوسط النتائج</span><strong>{average}%</strong></div>
        <div><span>دروس مكتملة</span><strong>{done}</strong></div>
        <div><span>اختبارات منجزة</span><strong>{results.filter((item) => item.quizPassed).length}</strong></div>
        <div><span>مسارات متقدمة</span><strong>{progress.filter((item) => item.progress >= 100).length}</strong></div>
      </section>
      <section className="profile-content">
        <div className="profile-panel">
          <div className="section-heading">
            <div><span className="eyebrow">تقدمك المحفوظ</span><h2>مساراتي التعليمية</h2></div>
          </div>
          {byStudyOrder(courses.filter((course) => aiLearningSlugs.has(course.slug)), courseStudyOrder).map((course) => {
            const item = progress.find((entry) => entry.courseSlug === course.slug);
            const value = item?.progress ?? 0;
            return (
              <button className="profile-course" key={course.slug} onClick={() => onNavigate(`/courses/${course.slug}/lessons/${Math.min((item?.completedLessons ?? 0) + 1, course.lessons.length)}`)}>
                <span className={`mini-glyph ${course.color}`}>{course.title.slice(0, 1)}</span>
                <span className="profile-course-main">
                  <strong>{course.title}</strong>
                  <small>{item?.completedLessons ?? 0}/{course.lessons.length} دروس مكتملة</small>
                  <i><b style={{ width: `${value}%` }} /></i>
                </span>
                <b className="profile-percent">{value}%</b>
                <span>←</span>
              </button>
            );
          })}
        </div>
        <div className="profile-panel results-panel">
          <div className="section-heading">
            <div><span className="eyebrow">مراجعة الأداء</span><h2>سجل نتائج الاختبارات</h2></div>
            <span className="result-count">{results.length} نتائج</span>
          </div>
          {results.length ? (
            <div className="results-list">
              {results.map((result) => {
                const course = courses.find((item) => item.slug === result.courseSlug);
                const percent = Math.round((result.quizScore / result.quizTotal) * 100);
                return (
                  <article className={`result-row ${result.quizPassed ? "passed" : "failed"}`} key={`${result.courseSlug}-${result.lessonIndex}`}>
                    <span className="result-number">{result.lessonIndex}</span>
                    <div>
                      <strong>{course?.title ?? result.courseSlug}</strong>
                      <small>الدرس {result.lessonIndex} · {new Date(result.updatedAt).toLocaleDateString("ar-IQ")}</small>
                    </div>
                    <span className="result-score">{percent}%<small>{result.quizScore}/{result.quizTotal}</small></span>
                    <span className="result-state">{result.quizPassed ? "مجتاز" : "إعادة"}<small>{result.attempts} محاولات</small></span>
                  </article>
                );
              })}
            </div>
          ) : (
            <div className="empty-state">أكمل اختبارًا ليظهر سجل نتائجك هنا.</div>
          )}
        </div>
      </section>
      <section className="profile-panel password-panel">
        <div className="section-heading"><div><span className="eyebrow">أمان الحساب</span><h2>تغيير كلمة المرور</h2></div></div>
        <form onSubmit={updatePassword} className="password-form"><input type="password" value={currentPassword} onChange={(event) => setCurrentPassword(event.target.value)} placeholder="كلمة المرور الحالية" required /><input type="password" value={newPassword} onChange={(event) => setNewPassword(event.target.value)} placeholder="كلمة المرور الجديدة (8 أحرف على الأقل)" minLength={8} required /><button className="primary-button" type="submit" disabled={passwordBusy}>{passwordBusy ? "جارٍ الحفظ..." : "حفظ كلمة المرور الجديدة"}</button>{passwordMessage && <small className="password-message">{passwordMessage}</small>}</form>
      </section>
    </main>
  );
}

function LessonPage({ course, index, user, progress, results, onNavigate, onProgressRefresh }: { course: Course; index: number; user: User | null; progress: Progress[]; results: QuizResult[]; onNavigate: (path: string) => void; onProgressRefresh: () => Promise<void> }) {
  const lesson = course.lessons[index - 1] ?? course.lessons[0];
  const courseProgress = progress.find((item) => item.courseSlug === course.slug);
  const allowed = course.slug === "engineering-projects" || (courseProgress?.completedLessons ?? 0) + 1 >= index;
  const [answers, setAnswers] = useState<Record<number, number>>({});
  const [submitted, setSubmitted] = useState(false);
  const [saving, setSaving] = useState(false);
  const [feedback, setFeedback] = useState<{ score: number; passed: boolean } | null>(null);
  const [showArabic, setShowArabic] = useState(false);
  const previousResult = results.find((item) => item.courseSlug === course.slug && item.lessonIndex === index);

  useEffect(() => { setAnswers({}); setSubmitted(false); setFeedback(null); setShowArabic(false); }, [course.slug, index]);

  if (!allowed) {
    return (
      <main className="lesson-shell">
        <Topbar user={user} active="learning" onNavigate={onNavigate} onLogout={() => undefined} />
        <section className="locked-card">
          <span>◈</span>
          <h1>هذا الدرس غير متاح بعد</h1>
          <p>أكمل الدرس السابق واجتز اختباره لفتح هذه الخطوة.</p>
          <button className="primary-button" onClick={() => onNavigate(`/courses/${course.slug}/lessons/${(courseProgress?.completedLessons ?? 0) + 1}`)}>
            العودة إلى الدرس المتاح ←
          </button>
        </section>
      </main>
    );
  }

  const submitQuiz = async () => {
    if (!user) {
      window.location.assign("/login");
      return;
    }
    setSubmitted(true);
    const score = lesson.quiz.reduce((sum, item, quizIndex) => sum + (answers[quizIndex] === item.answer ? 1 : 0), 0);
    const passed = score / lesson.quiz.length >= 0.7;
    setSaving(true);
    try {
      await api("/api/quiz/complete", { method: "POST", body: JSON.stringify({ courseSlug: course.slug, lessonIndex: index, score, total: lesson.quiz.length }) });
      setFeedback({ score, passed });
      await onProgressRefresh();
    } catch {
      setFeedback({ score, passed: false });
    } finally {
      setSaving(false);
    }
  };

  const next = index < course.lessons.length ? `/courses/${course.slug}/lessons/${index + 1}` : "/profile";
  const isFinalAssessment = index === course.lessons.length;
  const lessonExample = index === 1 ? 'name = "EngiMind"\nprint(f"مرحبًا بك في {name}")' : index === 2 ? 'scores = [80, 92, 75]\naverage = sum(scores) / len(scores)\nprint(average)' : index === 3 ? 'def greet(name):\n    return f"أهلًا {name}"\n\nprint(greet("علي"))' : 'class Project:\n    def __init__(self, title):\n        self.title = title\n\nproject = Project("مساعد ذكي")';

  return (
    <main className="lesson-shell">
      <Topbar user={user} active="learning" onNavigate={onNavigate} onLogout={() => undefined} />
      <div className="lesson-layout">
        <aside className="lesson-sidebar">
          <button className="back-link" onClick={() => onNavigate("/")}>→ العودة للمسارات</button>
          <span className="eyebrow">{course.title} · {courseEnglish[course.slug]?.title ?? course.title}</span>
          <h2>خطة المسار <small>Learning path</small></h2>
          {course.lessons.map((item, lessonIndex) => {
            const complete = (courseProgress?.completedLessons ?? 0) >= lessonIndex + 1;
            return (
              <button key={item.title} className={`lesson-nav ${lessonIndex + 1 === index ? "current" : ""} ${complete ? "complete" : ""}`} onClick={() => onNavigate(`/courses/${course.slug}/lessons/${lessonIndex + 1}`)}>
                <span>{complete ? "✓" : String(lessonIndex + 1).padStart(2, "0")}</span>
                <i>{item.title}<small>{item.duration}</small></i>
              </button>
            );
          })}
        </aside>
        <article className="lesson-content">
          <div className="lesson-heading">
            <span className={`course-chip ${course.color}`}>{course.level}</span>
            <span className="lesson-meta">الدرس {index} من {course.lessons.length} · Lesson {index} of {course.lessons.length} · {lesson.duration}</span>
            <h1>{lesson.title}</h1>
            <p>{lesson.summary}</p>
          </div>
          <div className="lesson-body">
            <span className="eyebrow">شرح المادة</span>
            {lesson.body.map((paragraph) => {
              const isMaterials = paragraph.startsWith("الأجهزة والمواد:");
              const isSteps = paragraph.startsWith("خطوات التنفيذ:");
              if (isMaterials || isSteps) {
                const [heading, details] = paragraph.split(":");
                return <section className="project-details" key={paragraph}><strong>{heading}</strong><ul>{details.split("،").map((item) => <li key={item}>{item.trim()}</li>)}</ul></section>;
              }
              return <p key={paragraph}>{paragraph}</p>;
            })}
            {course.slug === "engineering-projects" && <div className="safety-note"><strong>تنبيه السلامة</strong><p>استخدم جهدًا منخفضًا أثناء التجربة، افصل الطاقة قبل تغيير التوصيلات، ولا توصل دوائر Arduino مباشرة بكهرباء المنزل. اطلب إشراف شخص بالغ عند استخدام مضخة أو بطارية أو أدوات حرارية.</p></div>}
            {course.slug.includes("python") && <div className="video-lesson"><div className="video-lesson-heading"><span className="eyebrow">شرح بالفيديو</span><strong>Mastering Python مع Elzero Web School</strong></div><div className="video-frame"><iframe src="https://www.youtube.com/embed/videoseries?list=PLDoPjvoNmBAyE_gei5d18qkfIe-Z8mocs" title="Mastering Python - Elzero Web School" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowFullScreen /></div><small>المصدر: <a href="https://www.youtube.com/playlist?list=PLDoPjvoNmBAyE_gei5d18qkfIe-Z8mocs" target="_blank" rel="noreferrer">Elzero Web School على YouTube</a> — شاهد الفيديو المرتبط بالموضوع ثم طبّق المثال بنفسك.</small></div>}
            {course.slug === "cpp" && <div className="video-lesson"><div className="video-lesson-heading"><span className="eyebrow">فيديو الدرس {index}</span><strong>{cppVideos[index - 1]?.[1]} — Programming Advices</strong></div><div className="video-frame"><iframe src={`https://www.youtube.com/embed/${cppVideos[index - 1]?.[0] ?? cppVideos[0][0]}`} title={`${cppVideos[index - 1]?.[1] ?? "C++"} - Programming Advices`} allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowFullScreen /></div><p>شاهد شرح الدكتور محمد أبو هدهود، ثم طبّق الفكرة وحل اختبار الدرس.</p><small>المصدر: <a href="https://www.youtube.com/@ProgrammingAdvices" target="_blank" rel="noreferrer">Programming Advices</a>.</small></div>}
            {course.slug === "engineering-projects" && <div className="video-lesson"><div className="video-lesson-heading"><span className="eyebrow">فيديو تنفيذ المشروع</span><strong>{projectVideos[index - 1][1]}</strong></div>{projectVideos[index - 1][0] ? <div className="video-frame"><iframe src={`https://www.youtube.com/embed/videoseries?list=${projectVideos[index - 1][0]}`} title={projectVideos[index - 1][1]} allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowFullScreen /></div> : <a className="primary-button" href={`https://www.youtube.com/results?search_query=${encodeURIComponent(projectVideos[index - 1][1] + " Arduino tutorial")}`} target="_blank" rel="noreferrer">مشاهدة فيديوهات تنفيذ المشروع ↗</a>}<small>شاهد طريقة التنفيذ خطوة بخطوة، ثم طبّقها على النموذج التعليمي مع الالتزام بإرشادات السلامة.</small></div>}
            <div className="lesson-example"><strong>مثال عملي</strong><pre><code>{lessonExample}</code></pre><small>جرّب تغيير القيم في المثال، ثم اكتب النتيجة التي تتوقع ظهورها قبل تشغيل الكود.</small></div>
            <div className="lesson-practice"><strong>تمرين قبل الاختبار</strong><p>اكتب تطبيقًا صغيرًا يستخدم الفكرة التي تعلمتها في هذا الدرس، ثم راجع خطواتك وتأكد من أن النتيجة منطقية.</p></div>
          </div>
          <section className="quiz-card">
            <div className="quiz-heading">
              <span className="eyebrow">{isFinalAssessment ? "الاختبار النهائي · Final assessment" : "اختبر فهمك · Test your understanding"}</span>
              <h2>{isFinalAssessment ? "مشروع قصير واختبار نهائي" : "اختبار قصير قبل المتابعة"} <small>{isFinalAssessment ? "Capstone + final course exam" : "Progress assessment"}</small></h2>
              <p>{isFinalAssessment ? "نفّذ المشروع القصير ثم أجب عن الأسئلة واحصل على 70% أو أكثر لإكمال المسار." : "أجب عن الأسئلة واحصل على 70% على الأقل لفتح الدرس التالي. Answer at least 70% correctly to continue."}</p>
            </div>
            {lesson.quiz.map((item, quizIndex) => (
              <fieldset key={item.question}>
                <legend><span>{quizIndex + 1}. {showArabic ? item.question : (quizTranslations[item.question] ?? item.question)}</span><button type="button" className="translate-button" onClick={() => setShowArabic((current) => !current)}>{showArabic ? "English · English" : "ترجمة · Arabic"}</button><small className="quiz-en-label">{showArabic ? "السؤال · اختر أفضل إجابة" : "Question · Choose the best answer"}</small></legend>
                <div className="quiz-options">
                  {item.options.map((option, optionIndex) => (
                    <label key={option}>
                      <input type="radio" name={`question-${quizIndex}`} checked={answers[quizIndex] === optionIndex} onChange={() => setAnswers((current) => ({ ...current, [quizIndex]: optionIndex }))} disabled={saving} />
                      <span><b>{showArabic ? option : (quizTranslations[option] ?? option)}</b><small>Option {String.fromCharCode(65 + optionIndex)} · {showArabic ? `خيار الإجابة ${optionIndex + 1}` : `Answer option ${optionIndex + 1}`}</small></span>
                    </label>
                  ))}
                </div>
                {submitted && <small className={answers[quizIndex] === item.answer ? "answer-hint good" : "answer-hint bad"}>{answers[quizIndex] === item.answer ? (showArabic ? "إجابة صحيحة" : "Correct answer") : `${showArabic ? "الإجابة الصحيحة" : "Correct answer"}: ${showArabic ? item.options[item.answer] : (quizTranslations[item.options[item.answer]] ?? item.options[item.answer])}`} — {showArabic ? item.explanation : (quizTranslations[item.explanation] ?? item.explanation)}<br /><span><b>{showArabic ? "الحل:" : "Solution:"}</b> {showArabic ? `الخيار الصحيح هو ${String.fromCharCode(65 + item.answer)} لأنه يطابق هدف الدرس.` : `Option ${String.fromCharCode(65 + item.answer)} is correct because it best matches the lesson objective.`}</span></small>}
              </fieldset>
            ))}
            <div className="quiz-footer">
              <button className="primary-button" onClick={submitQuiz} disabled={saving || Object.keys(answers).length < lesson.quiz.length}>
                {saving ? "جارٍ الحفظ..." : feedback?.passed ? "تم الاجتياز ✓" : "تصحيح الاختبار"}
              </button>
              {feedback && <span className={feedback.passed ? "quiz-result success" : "quiz-result failure"}>{feedback.passed ? `أحسنت! نتيجتك ${feedback.score}/${lesson.quiz.length}` : `نتيجتك ${feedback.score}/${lesson.quiz.length}. أعد المحاولة للوصول إلى 70%.`}</span>}
            </div>
          </section>
          {feedback?.passed && <button className="next-lesson-button" onClick={() => onNavigate(next)}>{index < course.lessons.length ? "انتقل إلى الدرس التالي" : "عرض ملفي الشخصي"} <span>←</span></button>}
          {previousResult && !feedback && <p className="previous-attempt">آخر نتيجة محفوظة: {previousResult.quizScore}/{previousResult.quizTotal} · {previousResult.quizPassed ? "مجتاز" : "أعد المحاولة لتحسين النتيجة"}</p>}
        </article>
      </div>
    </main>
  );
}

export default function App() {
  const [user, setUser] = useState<User | null>(null);
  const [progress, setProgress] = useState<Progress[]>([]);
  const [results, setResults] = useState<QuizResult[]>([]);
  const [loading, setLoading] = useState(true);
  const path = window.location.pathname;
  const selectedGoal = new URLSearchParams(window.location.search).get("goal") || undefined;

  const navigate = (next: string) => {
    window.history.pushState({}, "", next);
    window.dispatchEvent(new Event("popstate"));
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const [, setRouteTick] = useState(0);

  useEffect(() => {
    const handler = () => setRouteTick((tick) => tick + 1);
    window.addEventListener("popstate", handler);
    return () => window.removeEventListener("popstate", handler);
  }, []);

  const refresh = async () => {
    try {
      const me = await api<{ user: User | null }>("/api/auth/me");
      setUser(me.user);
      if (me.user) {
        const [progressData, resultData] = await Promise.all([
          api<Progress[]>("/api/progress"),
          api<QuizResult[]>("/api/quiz-results")
        ]);
        setProgress(progressData);
        setResults(resultData);
      } else {
        setProgress([]);
        setResults([]);
      }
    } catch {
      setUser(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void refresh();
  }, []);

  const logout = async () => {
    try {
      await api("/api/auth/logout", { method: "POST" });
    } catch {
      // Ignore logout errors
    }
    setUser(null);
    setProgress([]);
    setResults([]);
    navigate("/");
  };

  const lessonMatch = path.match(/^\/courses\/([^/]+)\/lessons\/(\d+)$/);

  if (loading) return <div className="loading-screen"><span className="brand-mark">M</span><p>جارٍ تجهيز بوابتك...</p></div>;
  if (path === "/login") return <Login onBack={() => navigate("/")} />;
  if (path === "/forgot-password") return <ForgotPassword onBack={() => navigate("/login")} />;
  if (path === "/reset-password") return <ResetPassword token={new URLSearchParams(window.location.search).get("token") || ""} onBack={() => navigate("/login")} />;
  if (path === "/python") return <PythonPage user={user} progress={progress} onNavigate={navigate} onLogout={logout} />;
  if (path === "/python-lab") return <PythonLabPage user={user} onNavigate={navigate} onLogout={logout} />;
  if (path === "/portfolio") return <PortfolioPage user={user} onNavigate={navigate} onLogout={logout} />;
  if (path === "/data-lab") return <DataLabPage user={user} onNavigate={navigate} onLogout={logout} />;
  if (path === "/glossary") return <GlossaryPage user={user} onNavigate={navigate} onLogout={logout} />;
  if (path === "/exams") return <ExamsPage user={user} onNavigate={navigate} onLogout={logout} />;
  if (path === "/goals") return <GoalsPage user={user} onNavigate={navigate} onLogout={logout} />;
  if (path === "/review") return user ? <ReviewPage user={user} progress={progress} results={results} onNavigate={navigate} onLogout={logout} /> : <Login onBack={() => navigate("/")} />;
  if (path === "/search") return <SearchPage user={user} onNavigate={navigate} onLogout={logout} />;
  if (path === "/tracks") return <AdvancedTracksPage user={user} onNavigate={navigate} onLogout={logout} />;
  const advancedTrackMatch = path.match(/^\/tracks\/([^/]+)$/);
  if (advancedTrackMatch) return <AdvancedTracksPage user={user} onNavigate={navigate} onLogout={logout} slug={advancedTrackMatch[1]} />;
  if (path === "/projects") return <ProjectsPage user={user} onNavigate={navigate} onLogout={logout} />;
  if (path === "/community") return <CommunityPage user={user} onNavigate={navigate} onLogout={logout} />;
  if (path === "/notifications") return <NotificationsPage user={user} onNavigate={navigate} onLogout={logout} />;
  if (path === "/privacy") return <LegalPage kind="privacy" user={user} onNavigate={navigate} onLogout={logout} />;
  if (path === "/terms") return <LegalPage kind="terms" user={user} onNavigate={navigate} onLogout={logout} />;
  if (path === "/contact") return <LegalPage kind="contact" user={user} onNavigate={navigate} onLogout={logout} />;
  if (path === "/about") return <LegalPage kind="about" user={user} onNavigate={navigate} onLogout={logout} />;
  if (path === "/admin") return user ? <AdminPage user={user} onNavigate={navigate} onLogout={logout} /> : <Login onBack={() => navigate("/")} />;
  if (path === "/profile") return user ? <Profile user={user} progress={progress} results={results} onNavigate={navigate} onLogout={logout} /> : <Login onBack={() => navigate("/")} />;
  if (lessonMatch) {
    const course = courses.find((item) => item.slug === lessonMatch[1]);
    if (course) return user ? <LessonPage course={course} index={Number(lessonMatch[2])} user={user} progress={progress} results={results} onNavigate={navigate} onProgressRefresh={refresh} /> : <Login onBack={() => navigate("/")} />;
  }

  return <Home user={user} progress={progress} onNavigate={navigate} onLogout={logout} selectedGoal={selectedGoal} />;
}
